pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { 
        vm.deal(address(this), 2 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}(); 
    }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        bool ok;
        bytes32 hash = keccak256(abi.encodePacked(uint(1)));
        try c.lockInGuess{value: 1 ether}(hash) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
